module group_photo_area (\n    input clk, rst_n, start,\n    input [2:0] n,\n    input [9:0] max_h,\n    input [9:0] w0, h0, w1, h1, w2, h2, w3, h3,\n    input [9:0] w4, h4, w5, h5, w6, h6, w7, h7,\n    output reg [23:0] area,\n    output reg done\n);\n    localparam [2:0] IDLE  = 3'd0;\n    localparam [2:0] S1    = 3'd1;\n    localparam [2:0] S2    = 3'd2;\n    localparam [2:0] S3    = 3'd3;\n    localparam [2:0] FINISH = 3'd4;\n    localparam [2:0] ERROR = 3'd5;\n    reg [2:0] state, next_state;\n    reg [2:0] k, iter;\n    reg [9:0] w_arr [0:7];\n    reg [9:0] h_arr [0:7];\n    reg [12:0] total_w;\n    reg [2:0] sort_idx, sort_max;\n    reg swap_flag;\n    integer i;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            area <= 24'd0;\n            total_w <= 13'd0;\n            for (i = 0; i < 8; i = i + 1) begin\n                w_arr[i] <= 10'd0;\n                h_arr[i] <= 10'd0;\n            end\n        end else begin\n            state <= next_state;\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start && n >= 3'd1) begin\n                        k <= {1'b0, n[2:1]};  // k = floor(n/2)\n                        iter <= 3'd0;\n                        next_state <= S1;\n                    end\n                end\n\n                S1: begin\n                    // Load inputs into array\n                    case (iter)\n                        0: begin w_arr[iter] <= w0; h_arr[iter] <= h0; end\n                        1: begin w_arr[iter] <= w1; h_arr[iter] <= h1; end\n                        2: begin w_arr[iter] <= w2; h_arr[iter] <= h2; end\n                        3: begin w_arr[iter] <= w3; h_arr[iter] <= h3; end\n                        4: begin w_arr[iter] <= w4; h_arr[iter] <= h4; end\n                        5: begin w_arr[iter] <= w5; h_arr[iter] <= h5; end\n                        6: begin w_arr[iter] <= w6; h_arr[iter] <= h6; end\n                        7: begin w_arr[iter] <= w7; h_arr[iter] <= h7; end\n                    endcase\n\n                    // Force lies for over-height friends\n                    if (h_arr[iter] > max_h) begin\n                        if (k > 0 && w_arr[iter] <= max_h) begin\n                            w_arr[iter] <= h_arr[iter];\n                            h_arr[iter] <= w_arr[iter];\n                            k <= k - 3'd1;\n                        end else begin\n                            next_state <= ERROR;\n                        end\n                    end\n\n                    if (iter == 3'd7) begin\n                        sort_idx <= 3'd0;\n                        sort_max <= 3'd7;\n                        next_state <= S2;\n                        swap_flag <= 1'b0;\n                    end else begin\n                        iter <= iter + 3'd1;\n                    end\n                end\n\n                S2: begin\n                    // Bubble sort (h-w) ascending\n                    if ((h_arr[sort_idx] - w_arr[sort_idx]) > (h_arr[sort_idx+1] - w_arr[sort_idx+1])) begin\n                        // Swap elements\n                        w_arr[sort_idx]   <= w_arr[sort_idx+1];\n                        w_arr[sort_idx+1] <= w_arr[sort_idx];\n                        h_arr[sort_idx]   <= h_arr[sort_idx+1];\n                        h_arr[sort_idx+1] <= h_arr[sort_idx];\n                        swap_flag <= 1'b1;\n                    end\n\n                    if (sort_idx >= sort_max - 3'd1) begin\n                        sort_max <= sort_max - 3'd1;\n                        sort_idx <= 3'd0;\n                        if (swap_flag) begin\n                            swap_flag <= 1'b0;\n                        end else begin\n                            iter <= 3'd0;\n                            total_w <= 13'd0;\n                            next_state <= S3;\n                        end\n                    end else begin\n                        sort_idx <= sort_idx + 3'd1;\n                    end\n                end\n\n                S3: begin\n                    // Optimize remaining lies\n                    if (k > 0 && w_arr[iter] > h_arr[iter] && h_arr[iter] <= max_h) begin\n                        total_w <= total_w + h_arr[iter];\n                        k <= k - 3'd1;\n                    end else begin\n                        total_w <= total_w + w_arr[iter];\n                    end\n\n                    if (iter == 3'd7) begin\n                        area <= total_w * max_h;\n                        next_state <= FINISH;\n                    end else begin\n                        iter <= iter + 3'd1;\n                    end\n                end\n\n                FINISH: begin\n                    done <= 1'b1;\n                    if (!start) next_state <= IDLE;\n                end\n\n                ERROR: begin\n                    area <= 24'hFFFFFF;\n                    next_state <= FINISH;\n                end\n\n                default: next_state <= IDLE;\n            endcase\n        end\n    end\nendmodule